// Build human-readable option text for the WhatsApp template, and the data
// needed to save the proposal to Notion and notify the owner.
const j = $json;

function formatOption(iso) {
  if (!iso) return null;
  const d = new Date(iso);
  const date = d.toLocaleDateString('en-US', { weekday: 'short', day: 'numeric', month: 'short' });
  const time = d.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', hour12: true });
  return `${date}, ${time}`;
}

// Normalize the client's phone number to include the Singapore country
// code (+65), without double-adding it if it's already there.
function addSingaporeCode(phone) {
  if (!phone) return '';
  let cleaned = String(phone).replace(/[\s\-()]/g, '');

  if (cleaned.startsWith('+')) {
    // Already has a country code of some kind - leave it as is.
    return cleaned;
  }
  if (cleaned.startsWith('65') && cleaned.length > 8) {
    // Already has 65 prefix without the +.
    return '+' + cleaned;
  }
  if (cleaned.startsWith('0')) {
    // Local format like +10000000000 - drop the leading 0 before adding +65.
    cleaned = cleaned.slice(1);
  }
  return '+65' + cleaned;
}

const option1Text = formatOption(j.option1Start);
const option2Text = formatOption(j.option2Start) || option1Text;
const clientPhone = addSingaporeCode(j.clientPhone);

return [{
  json: {
    notionPageId: j.notionPageId,
    clientName: j.clientName,
    clientPhone: clientPhone,
    ownerPhone: j.ownerPhone,
    option1Start: j.option1Start,
    option2Start: j.option2Start,
    option1_text: option1Text,
    option2_text: option2Text,
    timeOptionsSummary: option2Text && option2Text !== option1Text
      ? `Option 1: ${option1Text} | Option 2: ${option2Text}`
      : `Option 1: ${option1Text}`
  }
}];

