// Parse the AI's constraint extraction, using the OpenAI Responses API output shape
const out = $json;

const aiRaw =
  out.output?.[0]?.content?.find(part => part?.type === 'output_text')?.text ||
  out.output?.[0]?.content?.[0]?.text ||
  out.text || out.content || out.message?.content ||
  out.choices?.[0]?.message?.content || out.output_text || '{}';

let parsed;
try {
  parsed = JSON.parse(String(aiRaw).replace(/```json|```/g, '').trim());
} catch (e) {
  parsed = { clientName: null, earliestDateIso: null, preferredTimeOfDay: 'any', notes: '' };
}

const trigger = $('Execute Workflow Trigger').first().json;

return [{
  json: {
    ownerPhone: trigger.ownerPhone,
    messageText: trigger.messageText,
    clientName: parsed.clientName || trigger.recipientNameGuess || null,
    earliestDateIso: parsed.earliestDateIso,
    preferredTimeOfDay: parsed.preferredTimeOfDay || 'any',
    notes: parsed.notes || ''
  }
}];

// Merge the found client's Notion record with the extracted scheduling constraints
const client = $json;
const constraints = $('Parse Extracted Constraints1').first().json;

return [{
  json: {
    notionPageId: (client.id || '').replace(/-/g, ''),
    clientName: client.property_name || constraints.clientName || 'Client',
    clientPhone: client.property_mobile_number || '',
    ownerPhone: constraints.ownerPhone,
    earliestDateIso: constraints.earliestDateIso,
    preferredTimeOfDay: constraints.preferredTimeOfDay
  }
}];

// Find up to TWO free 1-hour slots, 9am-5pm Mon-Fri, on or after the requested
// date (or tomorrow, if no date constraint given), honoring the owner's
// time-of-day preference where possible. We propose these to the client
// instead of auto-booking - they pick one via the WhatsApp template.
const busyEvents = $input.all().map(item => ({
  start: new Date(item.json.start?.dateTime || item.json.start?.date),
  end: new Date(item.json.end?.dateTime || item.json.end?.date)
})).filter(e => !isNaN(e.start) && !isNaN(e.end));

const client = $('Merge Client + Constraints1').first().json;

const businessStartHour = 9;
const businessEndHour = 17;
const slotLengthMin = 60;
const slotsNeeded = 2;

let cursor = client.earliestDateIso ? new Date(client.earliestDateIso) : new Date();
if (!client.earliestDateIso) cursor.setDate(cursor.getDate() + 1);
cursor.setHours(0, 0, 0, 0);

const searchWindowDays = 60;
const endDate = new Date(cursor);
endDate.setDate(endDate.getDate() + searchWindowDays);

const pref = (client.preferredTimeOfDay || 'any').toLowerCase();

function hourMatchesPref(h) {
  if (pref === 'morning') return h < 12;
  if (pref === 'afternoon') return h >= 12;
  return true;
}

function search(honorPref) {
  const found = [];
  for (let d = new Date(cursor); d <= endDate && found.length < slotsNeeded; d.setDate(d.getDate() + 1)) {
    const dow = d.getDay();
    if (dow === 0 || dow === 6) continue;
    for (let h = businessStartHour; h < businessEndHour; h += slotLengthMin / 60) {
      if (honorPref && !hourMatchesPref(h)) continue;
      const slotStart = new Date(d);
      slotStart.setHours(h, 0, 0, 0);
      const slotEnd = new Date(slotStart.getTime() + slotLengthMin * 60000);
      const overlaps = busyEvents.some(ev => slotStart < ev.end && slotEnd > ev.start);
      const alreadyFound = found.some(s => s.start === slotStart.toISOString());
      if (!overlaps && !alreadyFound && slotStart > new Date()) {
        found.push({ start: slotStart.toISOString(), end: slotEnd.toISOString() });
        if (found.length >= slotsNeeded) break;
      }
    }
  }
  return found;
}

// First pass: honor the time-of-day preference strictly
let slots = search(true);

// Fallback: if we couldn't fill both slots honoring the preference, top up ignoring it
if (slots.length < slotsNeeded) {
  const extra = search(false).filter(s => !slots.some(existing => existing.start === s.start));
  slots = slots.concat(extra).slice(0, slotsNeeded);
}

return [{
  json: {
    ...client,
    slotFound: slots.length > 0,
    slotCount: slots.length,
    option1Start: slots[0] ? slots[0].start : null,
    option1End: slots[0] ? slots[0].end : null,
    option2Start: slots[1] ? slots[1].start : null,
    option2End: slots[1] ? slots[1].end : null
  }
}];
